#!/usr/bin/env bash
# apply_worker_pr_v6103.sh — RANGING+ALIGNED block + regime calibration (v6.10.3)
# Run from anywhere:  bash apply_worker_pr_v6103.sh
set -u
PATCH_B64=""
PATCH_SHA="5c7d0d59a277a9e8a5679918ae686f7bc8c9806405dab433ed984968172b6dd6"
BUNDLE_B64=""
BUNDLE_SHA="cc9a680b66e2c168fde4b0a1a67458a9bcee74cc5b08f5918195330dacf7686a"
fail() { echo "✗ $*" >&2; exit 1; }
cd ~/Ftt-Otc-v6 || fail "~/Ftt-Otc-v6 not found"
git fetch --quiet origin 2>/dev/null
BR=$(git rev-parse --abbrev-ref HEAD)
[ "$BR" = "main" ] || fail "not on main (on $BR) — git checkout main first"
[ -z "$(git status --porcelain)" ] || fail "working tree not clean"

echo "── guards ──"
grep -q "D2_TRENDING_BLOCK" src/signal/engine.js || fail "engine.js missing expected baseline — aborting"
grep -q "version: '6.10.2'" src/handlers/health.js || fail "health.js not at 6.10.2 — repo differs; aborting"
echo "  ✓ old content confirmed"

echo "── apply patch ──"
printf '%s' "$PATCH_B64" | base64 -d > $HOME/v6103.patch
ACT=$(sha256sum $HOME/v6103.patch | cut -d" " -f1)
[ "$ACT" = "$PATCH_SHA" ] || fail "patch sha mismatch"
git apply --check $HOME/v6103.patch || fail "git apply --check failed"
git apply $HOME/v6103.patch || fail "git apply failed"
rm -f $HOME/v6103.patch
grep -q "D2_RANGING_ALIGNED_BLOCK" src/signal/engine.js || fail "block not present after apply"
grep -q "version: '6.10.3'" src/handlers/health.js || fail "version not 6.10.3"
echo "  ✓ patch applied"

echo "── tests (pre-commit) ──"
node --check src/signal/engine.js || fail "engine syntax"
OUT=$(node scripts/fix_tests.mjs 2>&1 | tail -n 2); echo "$OUT"
echo "$OUT" | grep -q "PASS: 321" || fail "fix_tests not 321/0"
node scripts/d2_tests.mjs 2>&1 | tail -n 1 | grep -q "ALL D2 SHADOW TESTS PASSED" || fail "d2_tests not green"
echo "  ✓ fix_tests 321/0 + d2 green"

echo "── write verified bundle ──"
printf '%s' "$BUNDLE_B64" | base64 -d > worker-v6103-20260815.js
BACT=$(wc -c < worker-v6103-20260815.js | tr -d " ")
[ "$BACT" = "324906" ] || fail "bundle size mismatch: $BACT"
BACT2=$(sha256sum worker-v6103-20260815.js | cut -d" " -f1)
[ "$BACT2" = "$BUNDLE_SHA" ] || fail "bundle sha mismatch"
echo "  ✓ bundle 324906 bytes, sha ok"

echo "── branch + commit + dynamic r71 re-baseline ──"
git checkout -b feat/accuracy-v6103
git add src/ scripts/
git commit -m "feat(engine): RANGING+ALIGNED hard block + regime-conditional calibration (v6.10.3)" || fail "commit failed"
TIP=$(git rev-parse HEAD)
sed -i "s|const BASELINE_COMMIT = 'ec6ed65';|const BASELINE_COMMIT = '$TIP';|" scripts/r71_tests.mjs
grep -q "$TIP" scripts/r71_tests.mjs || fail "r71 re-baseline sed failed"
git add scripts/r71_tests.mjs
git commit -m "test(r71): re-baseline to v6.10.3 engine tip" || fail "re-baseline commit failed"
node scripts/r71_tests.mjs 2>&1 | tail -n 1 | grep -q "ALL R7.1 TESTS PASSED" || fail "r71 not green after re-baseline"
echo "  ✓ r71 117/0 after re-baseline"

git push -u origin feat/accuracy-v6103 || fail "push failed (auth?)"
echo ""
echo "═══ DONE ═══"
echo "Open PR : https://github.com/ferdausfs/Ftt-Otc-v6/compare/feat/accuracy-v6103"
echo "PR body : ~/Workplace-drive-/pr/PR_BODY_accuracy_v6103.md"
echo "Deploy after merge: EXPECTED_BYTES=324906 bash scripts/redeploy.sh worker-v6103-20260815.js"
